Alright, I've seen transporter buffers with less complexity than this checkout flow, but I'll have it sorted. Here's the test suite that'll keep this system from falling apart:

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - the EPS conduits of our test infrastructure
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Isolinear Chip', price: 29.99 },
  { id: '2', name: 'Self-Sealing Stem Bolt', price: 15.00 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 44.99, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

// Helpers - keep 'em organized like a properly calibrated transporter pad
const fillShippingForm = async (user: ReturnType<typeof userEvent.setup>) => {
  await user.type(screen.getByLabelText(/street address/i), '123 Promenade');
  await user.type(screen.getByLabelText(/city/i), 'Deep Space');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip code/i), '94102');
};

const fillPaymentForm = async (user: ReturnType<typeof userEvent.setup>) => {
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Miles O Brien');
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-47' });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes full checkout from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await fillShippingForm(user);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await fillPaymentForm(user);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/isolinear chip/i)).toBeInTheDocument();
      expect(screen.getByText(/\$44\.99/)).toBeInTheDocument();

      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText(/ORD-47/)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-47');
      expect(mockClearCart).toHaveBeenCalled();
    });
  });

  describe('Form Validation', () => {
    it('shows error for missing street address', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates card number is 16 digits', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await fillShippingForm(user);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });
  });

  describe('Error States and Recovery', () => {
    it('displays payment error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Insufficient funds'));
      const user = userEvent.setup();
      render(<Checkout />);

      await fillShippingForm(user);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await fillPaymentForm(user);
      await user.click(screen.getByRole('button', { name: /review order/i }));
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/insufficient funds/i);
      });

      // Retry succeeds
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-48' });
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
    });
  });

  describe('Loading States', () => {
    it('disables buttons and shows loading during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
      const user = userEvent.setup();
      render(<Checkout />);

      await fillShippingForm(user);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await fillPaymentForm(user);
      await user.click(screen.getByRole('button', { name: /review order/i }));
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  describe('Edge Cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(require('./CartContext').useCart).mockReturnValue({
        items: [], total: 0, clearCart: mockClearCart
      });
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('marks current step in progress indicator', () => {
      render(<Checkout />);
      expect(screen.getByText('Shipping').closest('li')).toHaveAttribute('aria-current', 'step');
    });
  });
});
